corrected_code:
app.get('/api/orders/:orderId/shipping-events', authenticate, async (req, res) => {
  const order = await Order.findOne({ where: { id: req.params.orderId, customerId: req.user.id } });
  if (!order) {
    return res.status(403).json({ error: 'Forbidden: you are not the owner of this order' });
  }

  res.writeHead(200, {
    'Content-Type': 'text/event-stream',
    'Cache-Control': 'no-cache',
    Connection: 'keep-alive'
  });

  const onMilestone = (milestone) => {
    res.write(`data: ${JSON.stringify(milestone)}\n\n`);
  };

  orderEvents.on(`order:${req.params.orderId}`, onMilestone);
  req.on('close', () => {
    orderEvents.off(`order:${req.params.orderId}`, onMilestone);
  });
});
